INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20C1JHU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A hemisphere with a diameter of $18$ cm sits on a flat surface. What is the volume of the hemisphere, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$243\\pi$"},{"key":"B","text":"$486\\pi$"},{"key":"C","text":"$729\\pi$"},{"key":"D","text":"$972\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct volume is $486\\pi$ cubic centimeters. The diameter is $18$ cm, so the radius is $9$ cm. The volume of a hemisphere is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(9)^3 = \\frac{2}{3}\\pi(729) = 486\\pi$. The value $243\\pi$ results from using $\\frac{1}{3}\\pi r^3$, applying the cone volume formula instead of the hemisphere formula. The value $729\\pi$ comes from computing $\\pi r^3 = \\pi(729)$, treating the hemisphere as a cylinder with height equal to the radius. The value $972\\pi$ results from computing the full sphere volume $\\frac{4}{3}\\pi(729) = 972\\pi$ without halving for the hemisphere.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20O2ZQV', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of $x$ satisfies the equation $$7(2x + 3) - 5(3x - 4) = 11 - 4x\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-30$"},{"key":"B","text":"$-10$"},{"key":"C","text":"$2$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $14x + 21 - 15x + 20 = 11 - 4x$. Combining like terms on the left yields $-x + 41 = 11 - 4x$. Adding $4x$ to both sides gives $3x + 41 = 11$. Subtracting $41$ from both sides gives $3x = -30$, so $x = -10$. The value $-30$ results from an arithmetic slip where the solver finds $3x = -30$ but reports $-30$ as the answer without dividing by $3$. The value $2$ arises from a sign error in distributing $-5$ over $(3x - 4)$, incorrectly obtaining $-15x - 4$ instead of $-15x + 20$, which leads to $-x + 17 = 11 - 4x$ and $3x = -6$ giving $x = -2$, then dropping the negative. The value $10$ comes from partial reasoning where the solver correctly finds $x = -10$ but drops the negative sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20RQ8VK', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ is defined by the equation $5x + 2y = 18$. Line $n$ is perpendicular to line $m$ and passes through the point $(10, -3)$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$1$"},{"key":"C","text":"$7$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $m$ in slope-intercept form gives $y = -\\frac{5}{2}x + 9$, so the slope of line $m$ is $-\\frac{5}{2}$. A line perpendicular to $m$ has slope $\\frac{2}{5}$. Using point-slope form with $(10, -3)$: $y - (-3) = \\frac{2}{5}(x - 10)$, which gives $y + 3 = \\frac{2}{5}x - 4$, so $y = \\frac{2}{5}x - 7$. The $y$-intercept is $-7$. The value $1$ comes from using the slope $-\\frac{2}{5}$ instead of $\\frac{2}{5}$, taking the reciprocal but not negating; this gives $y + 3 = -\\frac{2}{5}(x - 10) = -\\frac{2}{5}x + 4$, so $y = -\\frac{2}{5}x + 1$ with $y$-intercept $1$. The value $7$ results from a sign error, negating $-7$ to get $7$. The value $22$ arises from using the same slope $-\\frac{5}{2}$ as line $m$ (a parallel line rather than perpendicular), giving $y + 3 = -\\frac{5}{2}(x - 10) = -\\frac{5}{2}x + 25$, so $y = -\\frac{5}{2}x + 22$ with $y$-intercept $22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM218XAEJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 + 18x + 29$. The function $g$ is defined by $g(x) = f(x - 4) + 5$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 3(x^2 + 6x) + 29 = 3(x^2 + 6x + 9 - 9) + 29 = 3(x + 3)^2 - 27 + 29 = 3(x + 3)^2 + 2$. The minimum value of $f$ is $2$. Now, $g(x) = f(x - 4) + 5 = 3((x - 4) + 3)^2 + 2 + 5 = 3(x - 1)^2 + 7$. Since $(x - 1)^2 \\geq 0$, the minimum of $g$ is $7$, occurring at $x = 1$. The distractor $2$ comes from finding the minimum of $f$ without applying the vertical shift of $+5$. The distractor $5$ results from assuming the minimum of $f$ is $0$ and only applying the $+5$ shift. The distractor $-3$ results from a sign error, computing $2 - 5 = -3$ instead of $2 + 5 = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21LDPZN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sold $84$ books on Monday and $63$ books on Tuesday. What is the percent decrease in the number of books sold from Monday to Tuesday?', NULL, $lyceon_json$[{"key":"A","text":"$21\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33\\%$"},{"key":"D","text":"$75\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease is $84 - 63 = 21$ books. The percent decrease is $\\frac{21}{84} \\times 100 = 25\\%$. The value $21\\%$ confuses the absolute decrease of $21$ books with the percent decrease. The value $33\\%$ results from dividing the decrease by Tuesday''s total instead of Monday''s: $\\frac{21}{63} \\approx 33.3\\%$. The value $75\\%$ computes $\\frac{63}{84} = 75\\%$, which is the percentage of Monday''s sales that remained, not the percent decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2409AH0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A drawer contains $11$ black socks, $7$ navy socks, and $3$ gray socks. If one sock is selected at random, what is the probability that it is navy?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{21}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{7}{11}$"},{"key":"D","text":"$\\frac{1}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of socks is $11 + 7 + 3 = 21$. The probability of selecting a navy sock is $\\frac{7}{21}$, which simplifies to $\\frac{1}{3}$. The value $\\frac{7}{18}$ results from miscounting the total as $18$ by omitting the gray socks. The value $\\frac{7}{11}$ uses only the black sock count as the denominator rather than the total. The value $\\frac{1}{7}$ confuses the count of navy socks with the total number of socks.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24AVIRZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set of $6$ values has a mean of $53$. When two new values, $41$ and $69$, are added to the data set, what is the mean of the resulting $8$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '53.5', ARRAY['107/2', '53.5'], E'The sum of the original $6$ values is $6 \\times 53 = 318$. Adding $41$ and $69$ gives a new sum of $318 + 41 + 69 = 428$. The mean of the $8$ values is $\\frac{428}{8} = 53.5$. A common error is to average the two new values with the old mean: $\\frac{53 + 41 + 69}{3} \\approx 54.3$, which does not properly weight by the number of values. Another error is to divide by $6$ instead of $8$ after adding the new values, giving $\\frac{428}{6} \\approx 71.3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24OFHG0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $41^\\circ$ and $76^\\circ$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$53^\\circ$"},{"key":"B","text":"$73^\\circ$"},{"key":"C","text":"$63^\\circ$"},{"key":"D","text":"$117^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of interior angles in any triangle is $180^\\circ$. The third angle is $180 - 41 - 76 = 63$, so the correct measure is $63^\\circ$. The value $53^\\circ$ results from an arithmetic slip, such as computing $41 + 76 = 127$ instead of $117$. The value $73^\\circ$ arises from a different arithmetic slip in the subtraction step, for example treating $180 - 117$ as $73$. The value $117^\\circ$ results from misreading the question and reporting the sum of the two given angles rather than the missing third angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RQE3F', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $p$ is defined by $p(x) = 3^{x+2} - 7$. Which of the following describes the range of $p$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $-7$"},{"key":"B","text":"All real numbers greater than or equal to $-7$"},{"key":"C","text":"All real numbers greater than $2$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'The base exponential $3^{x+2}$ is always positive for all real $x$, approaching $0$ as $x \\to -\\infty$ but never equaling $0$. Subtracting $7$ shifts the output down by $7$, so $p(x) > -7$ for all $x$, but $p(x)$ never equals $-7$. Therefore the range is all real numbers greater than $-7$. The choice stating greater than or equal to $-7$ incorrectly includes $-7$, which would require $3^{x+2} = 0$, an impossibility for exponential functions. The choice stating greater than $2$ confuses the horizontal shift parameter with the vertical asymptote. The choice stating all real numbers ignores that exponential functions with a positive base always produce positive outputs, making values at or below $-7$ unreachable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM260YARE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $220$ residents of a county found that $43\\%$ approve of a proposed bike lane expansion, with a margin of error of $6$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $43\\%$ of all county residents approve of the bike lane expansion."},{"key":"B","text":"It is plausible that between $37\\%$ and $49\\%$ of all county residents approve of the bike lane expansion."},{"key":"C","text":"Between $37\\%$ and $49\\%$ of the sampled residents approve of the bike lane expansion."},{"key":"D","text":"If the survey is repeated, exactly $43\\%$ of the new sample will approve of the bike lane expansion."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $6$ percentage points means the plausible range for the population proportion is $43\\% \\pm 6\\%$, or between $37\\%$ and $49\\%$. This interval applies to the entire population of county residents. The claim that exactly $43\\%$ of all residents approve treats the sample statistic as the exact population value, ignoring sampling variability. The claim that the interval describes the sampled residents confuses the sample, which was directly observed at $43\\%$, with the population inference. The claim that a new sample would yield exactly $43\\%$ misunderstands that different random samples produce different results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26AU2BL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 8y = 23$$ $$5x + 10y = 31$$ In the system of equations above, $k$ is a constant. If the system has no solution, what is the value of $k$ ?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\frac{5}{2}$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$\\frac{4}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants is different. Setting $\\frac{k}{5} = \\frac{8}{10}$ gives $\\frac{k}{5} = \\frac{4}{5}$, so $k = 4$. Checking the constants: $\\frac{23}{31} \\neq \\frac{4}{5}$ (since $\\frac{4}{5} = 0.8$ and $\\frac{23}{31} \\approx 0.742$), confirming the system is inconsistent when $k = 4$. The value $\\frac{5}{2}$ results from incorrectly setting $\\frac{k}{5} = \\frac{10}{8}$ instead of $\\frac{8}{10}$, reversing the ratio of the $y$-coefficients. The value $-4$ introduces an erroneous negative sign when solving $\\frac{k}{5} = \\frac{4}{5}$ for $k$. The value $\\frac{4}{5}$ is the simplified ratio $\\frac{8}{10}$ itself rather than the result of solving $\\frac{k}{5} = \\frac{4}{5}$ for $k$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26C3TXT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid metal sphere with a radius of $9$ cm is melted down and recast into a solid right circular cylinder with a base radius of $6$ cm. What is the height of the resulting cylinder, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$9$"},{"key":"C","text":"$27$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct height is $27$ cm. The volume of the sphere is $\\frac{4}{3}\\pi r^3 = \\frac{4}{3}\\pi(9)^3 = \\frac{4}{3}\\pi(729) = 972\\pi$ cubic centimeters. Setting this equal to the cylinder volume $\\pi R^2 h = \\pi(6)^2 h = 36\\pi h$ gives $36\\pi h = 972\\pi$, so $h = 27$. The value $3$ results from using $r^2$ instead of $r^3$ in the sphere volume formula, computing $\\frac{4}{3}\\pi(81) = 108\\pi$ and then $108/36 = 3$. The value $9$ comes from using the sphere surface area formula $4\\pi r^2 = 4\\pi(81) = 324\\pi$ instead of the volume, yielding $324/36 = 9$. The value $81$ results from omitting the $\\frac{1}{3}$ in $\\frac{4}{3}$, computing $4\\pi(729) = 2916\\pi$ and then $2916/36 = 81$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28EVZ7R', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$4x + 3y = 29$$ $$4x - 3y = 11$$ What is the value of $x$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Adding the two equations eliminates $y$: $(4x + 3y) + (4x - 3y) = 29 + 11$, which gives $8x = 40$, so $x = 5$. This can be verified by substituting back: $4(5) + 3y = 29$ gives $3y = 9$, so $y = 3$, and checking the second equation: $4(5) - 3(3) = 20 - 9 = 11$, which is correct.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29Z4GEM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A company''s revenue was $240{,}000$ dollars in the first quarter. Revenue increased by $18\\%$ in the second quarter and then decreased by $22\\%$ in the third quarter. What was the revenue, in dollars, in the third quarter?', NULL, $lyceon_json$[{"key":"A","text":"$220{,}896$"},{"key":"B","text":"$230{,}400$"},{"key":"C","text":"$240{,}000$"},{"key":"D","text":"$283{,}200$"}]$lyceon_json$::jsonb, 'A', NULL, E'Second quarter revenue is $240{,}000 \\times 1.18 = 283{,}200$ dollars. Third quarter revenue after a $22\\%$ decrease is $283{,}200 \\times 0.78 = 220{,}896$ dollars. The value $230{,}400$ results from applying only the net percentage change of $18\\% - 22\\% = -4\\%$ to the original: $240{,}000 \\times 0.96 = 230{,}400$, which incorrectly assumes percentage changes are additive. The value $240{,}000$ assumes the increase and decrease cancel out, leaving revenue unchanged. The value $283{,}200$ is the second quarter revenue, reflecting a failure to apply the third quarter decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4R46G', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line that passes through the points $(7, -19)$ and $(-5, 29)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$-\\frac{1}{4}$"},{"key":"C","text":"$\\frac{1}{4}$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope formula gives $m = \\frac{29 - (-19)}{-5 - 7} = \\frac{48}{-12} = -4$. The value $-\\frac{1}{4}$ results from inverting the fraction, computing the change in $x$ over the change in $y$ instead of rise over run. The value $\\frac{1}{4}$ compounds the inversion error with a sign error, losing the negative. The value $4$ results from dropping the negative sign from the correct calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AZF2Y8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A biologist records the number of hours of artificial light per day, $x$, and the growth, in millimeters, of a plant specimen after $21$ days, $y$. The equation of the line of best fit is $y = 2.9x + 6.1$. Which of the following is the best interpretation of the number $6.1$ in this equation?', NULL, $lyceon_json$[{"key":"A","text":"A plant that receives no artificial light is predicted to grow $6.1$ millimeters after $21$ days."},{"key":"B","text":"For each additional hour of artificial light per day, the predicted growth increases by $6.1$ millimeters."},{"key":"C","text":"A plant that receives $6.1$ hours of artificial light per day is predicted to grow $2.9$ millimeters."},{"key":"D","text":"The plant grows $6.1$ millimeters each day."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 2.9x + 6.1$, the constant $6.1$ is the $y$-intercept, which represents the predicted value of $y$ when $x = 0$. In context, when the plant receives $0$ hours of artificial light per day, the predicted growth after $21$ days is $6.1$ millimeters. The interpretation that each additional hour increases growth by $6.1$ millimeters confuses the $y$-intercept with the slope, which is $2.9$. The interpretation involving $6.1$ hours of light with $2.9$ millimeters of growth swaps the roles of the slope and intercept entirely. The interpretation that the plant grows $6.1$ millimeters each day misidentifies the units: the model predicts total growth over $21$ days, not daily growth.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BWROEN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A paint mixture requires $7$ parts blue pigment and $3$ parts white pigment by volume. Blue pigment costs $3.40$ dollars per liter and white pigment costs $2.60$ dollars per liter. What is the cost, in dollars per liter, of the paint mixture?', NULL, $lyceon_json$[{"key":"A","text":"$3.00$"},{"key":"B","text":"$3.16$"},{"key":"C","text":"$3.40$"},{"key":"D","text":"$6.00$"}]$lyceon_json$::jsonb, 'B', NULL, E'In $10$ liters of mixture ($7 + 3$), the cost of blue pigment is $7 \\times 3.40 = 23.80$ dollars and the cost of white pigment is $3 \\times 2.60 = 7.80$ dollars. The total cost is $23.80 + 7.80 = 31.60$ dollars for $10$ liters, so the cost per liter is $\\frac{31.60}{10} = 3.16$ dollars. The value $3.00$ results from taking the simple average $\\frac{3.40 + 2.60}{2} = 3.00$ instead of using the weighted average based on the volume ratio. The value $3.40$ ignores the white pigment entirely and uses only the blue pigment cost. The value $6.00$ comes from adding the two unit prices $3.40 + 2.60 = 6.00$ without weighting or dividing by the total volume.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E0HTW8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new scheduling app increases employee productivity. They recruit $240$ employees from four offices of the same company ($60$ per office). At each office, $30$ employees are randomly assigned to use the new app and $30$ continue with the existing system. After $10$ weeks, productivity scores are compared. A reviewer notes that all four offices are in the same metropolitan area and employ workers in similar technical roles. Which of the following is the most significant limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"The study does not use random assignment, so causation cannot be established."},{"key":"B","text":"A sample of $240$ employees is insufficient to detect any meaningful difference in productivity."},{"key":"C","text":"Because the offices share similar locations and job types, the results may not generalize to employees in different industries or regions."},{"key":"D","text":"Ten weeks is not enough time for any scheduling app to affect productivity."}]$lyceon_json$::jsonb, 'C', NULL, E'The study does use random assignment within each office, so it can establish a causal relationship for the population it represents. However, all four offices are in the same metropolitan area with employees in similar technical roles, so the results may not generalize to employees in different industries, regions, or job types. The claim that the study lacks random assignment is factually incorrect — employees were randomly assigned to treatment groups at each office. The claim that $240$ employees is too small is not the most significant limitation; this sample size is reasonable for detecting moderate effects in a controlled experiment. The claim that ten weeks is too short makes an unsupported assumption and is not the limitation identified by the reviewer''s observation about the homogeneity of the sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E6979S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $RST$, angle $T$ is the right angle, $RS = 35$, and $\\sin R = \\frac{3}{5}$. Point $U$ is on $\\overline{RS}$ such that $\\overline{TU}$ is perpendicular to $\\overline{RS}$. What is the length of $\\overline{TU}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '84/5', ARRAY['84/5', '16.8'], E'The correct answer is $\\frac{84}{5}$. Since $\\sin R = \\frac{3}{5}$ and the hypotenuse $RS = 35$, the side opposite angle $R$ is $ST = 35 \\times \\frac{3}{5} = 21$, and the side adjacent to angle $R$ is $RT = 35 \\times \\frac{4}{5} = 28$ (using the Pythagorean relationship $\\cos R = \\frac{4}{5}$). The area of triangle $RST$ can be computed as $\\frac{1}{2}(RT)(ST) = \\frac{1}{2}(28)(21) = 294$. Setting this equal to $\\frac{1}{2}(RS)(TU)$ gives $\\frac{1}{2}(35)(TU) = 294$, so $TU = \\frac{588}{35} = \\frac{84}{5}$. A common error is using $\\sin R$ directly with side $RS$ to get $TU = 35 \\times \\frac{3}{5} = 21$, confusing the altitude to the hypotenuse with the leg opposite angle $R$. Another error is computing only one leg and stopping without finding the altitude.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EFD8A0', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{6x^3 - 54x}{3x^2 - 9x}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 6$"},{"key":"B","text":"$2x + 6$"},{"key":"C","text":"$2x + 3$"},{"key":"D","text":"$2x^2 + 6x$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator: $6x^3 - 54x = 6x(x^2 - 9) = 6x(x - 3)(x + 3)$. Factor the denominator: $3x^2 - 9x = 3x(x - 3)$. Cancel the common factors $3x$ and $(x - 3)$: $\\frac{6x(x - 3)(x + 3)}{3x(x - 3)} = 2(x + 3) = 2x + 6$. The distractor $2x - 6$ results from a sign error, writing $2(x - 3)$ instead of $2(x + 3)$ after cancellation. The distractor $2x + 3$ comes from partial reasoning, correctly finding the factor $2$ and $(x + 3)$ but failing to distribute the $2$, as if the result were $2x + 3$ rather than $2(x + 3)$. The distractor $2x^2 + 6x$ results from cancelling only the $3$ from numerator and denominator without also cancelling the common factor $x(x - 3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EGNQQN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same large population of registered voters. Sample P consists of $200$ voters and finds that $47\\%$ support a ballot measure, with a margin of error of $\\pm 7.1$ percentage points. Sample Q consists of $800$ voters and finds that $52\\%$ support the ballot measure, with a margin of error of $\\pm 3.5$ percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The true population proportion is $52\\%$ because Sample Q has a smaller margin of error."},{"key":"B","text":"The confidence intervals from both samples overlap, so the results are consistent with each other."},{"key":"C","text":"The results contradict each other, so both samples must contain bias."},{"key":"D","text":"Since both samples are from the same population, the true proportion must equal the average of $47\\%$ and $52\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample P''s confidence interval is $39.9\\%$ to $54.1\\%$, and Sample Q''s confidence interval is $48.5\\%$ to $55.5\\%$. These intervals overlap in the range from about $48.5\\%$ to $54.1\\%$, so both results are consistent with each other and could reflect the same population proportion. The claim that the true proportion is $52\\%$ because Sample Q has a smaller margin of error confuses a narrower interval with certainty about the point estimate — a smaller margin of error means greater precision, not that the point estimate equals the parameter. The claim that the results contradict each other misunderstands that different samples naturally produce different point estimates; the overlapping intervals show no contradiction. The claim that the true proportion must equal the average of the two estimates has no statistical basis — the population proportion is a fixed value, not determined by averaging sample results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EMVKNW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A plumber charges a flat service call fee plus an hourly rate. The total charge for a 2-hour job is 203 dollars, and the total charge for a 9-hour job is 658 dollars. The plumber then raises the flat fee by 19 dollars and reduces the hourly rate by 6 dollars. Under the new pricing, what is the total charge, in dollars, for a 6-hour job?', NULL, $lyceon_json$[{"key":"A","text":"$427$"},{"key":"B","text":"$446$"},{"key":"C","text":"$463$"},{"key":"D","text":"$482$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $r$ be the hourly rate and $f$ be the flat fee. From the given information, $2r + f = 203$ and $9r + f = 658$. Subtracting the first equation from the second gives $7r = 455$, so $r = 65$. Substituting back yields $f = 203 - 2(65) = 203 - 130 = 73$. The new rate is $65 - 6 = 59$ dollars per hour and the new flat fee is $73 + 19 = 92$ dollars. For a 6-hour job: $59(6) + 92 = 354 + 92 = 446$ dollars. The value $427$ results from applying only the rate decrease while keeping the original flat fee: $59(6) + 73 = 354 + 73 = 427$. The value $463$ results from using the original pricing without any adjustments: $65(6) + 73 = 390 + 73 = 463$. The value $482$ results from applying only the fee increase while keeping the original hourly rate: $65(6) + 92 = 390 + 92 = 482$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ETCFG7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following is the solution to the inequality $6x - 23 > 31$ ?', NULL, $lyceon_json$[{"key":"A","text":"$x > 9$"},{"key":"B","text":"$x > 54$"},{"key":"C","text":"$x < 9$"},{"key":"D","text":"$x > \\frac{4}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $23$ to both sides of $6x - 23 > 31$ gives $6x > 54$. Dividing both sides by $6$ yields $x > 9$. The result $x > 54$ comes from computing $6x > 54$ but stopping before dividing by $6$, treating the intermediate result as the answer. The inequality $x < 9$ reverses the direction of the inequality sign, reflecting a misconception that solving an inequality always flips the sign. The result $x > \\frac{4}{3}$ arises from subtracting $23$ from $31$ to get $8$ and then dividing $8$ by $6$, an error in the initial arithmetic step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FETIXA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A cyclist travels $37$ kilometers in $2$ hours and $30$ minutes. At this constant speed, how many kilometers does the cyclist travel in $45$ minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11.1', ARRAY['11.1'], E'First, convert $2$ hours and $30$ minutes to $2.5$ hours. The speed is $\\frac{37}{2.5} = 14.8$ kilometers per hour. Next, convert $45$ minutes to $0.75$ hours. The distance traveled in $0.75$ hours is $14.8 \\times 0.75 = 11.1$ kilometers. A common error is to use $2.3$ hours instead of $2.5$ hours when converting $2$ hours $30$ minutes, which gives an incorrect speed. Another error is to convert $45$ minutes as $\\frac{45}{100} = 0.45$ hours instead of $\\frac{45}{60} = 0.75$ hours, resulting in a unit conversion mistake.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G0SWDX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 50x + 14y + 49 = 0$ defines a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$\\sqrt{674}$"},{"key":"C","text":"$625$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct radius is $25$. Completing the square: group the $x$-terms and $y$-terms as $(x^2 - 50x) + (y^2 + 14y) = -49$. Completing the square for $x$: $(x^2 - 50x + 625) = (x - 25)^2$ adds $625$. For $y$: $(y^2 + 14y + 49) = (y + 7)^2$ adds $49$. So $(x - 25)^2 + (y + 7)^2 = -49 + 625 + 49 = 625$, giving $r^2 = 625$ and $r = 25$. The value $5$ results from an arithmetic slip such as computing $\\sqrt{25}$ from misidentifying $r^2 = 25$ instead of $r^2 = 625$. The value $\\sqrt{674}$ comes from computing $\\sqrt{25^2 + 7^2}$ using the center coordinates as though they determine the radius. The value $625$ results from reporting $r^2$ without taking the square root to find $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5P9UN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'At a festival, $54$ attendees each chose exactly one of three activities: pottery, weaving, or glassblowing. There are $23$ attendees doing pottery, $19$ doing weaving, and $12$ doing glassblowing. Of the pottery attendees, $8$ are under age $18$. Of the weaving attendees, $11$ are under age $18$. Of the glassblowing attendees, $3$ are under age $18$. An attendee is selected at random. Given that the selected attendee is age $18$ or older, what is the probability that this attendee chose weaving? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/4', ARRAY['1/4', '0.25', '.25'], E'The total number of attendees under $18$ is $8 + 11 + 3 = 22$, so the number of attendees age $18$ or older is $54 - 22 = 32$. The number of weaving attendees age $18$ or older is $19 - 11 = 8$. The conditional probability is $\\frac{8}{32} = \\frac{1}{4}$. A common error is to compute $\\frac{19}{54}$, the unconditional probability of choosing weaving without restricting to attendees age $18$ or older. Another error is to find the correct numerator of $8$ but divide by $54$ rather than $32$, yielding $\\frac{8}{54}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GINZUL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $13$ and the hypotenuse has length $85$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$84$"},{"key":"C","text":"$82$"},{"key":"D","text":"$\\sqrt{7394}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $a^2 + b^2 = c^2$, so the other leg is $\\sqrt{85^2 - 13^2} = \\sqrt{7225 - 169} = \\sqrt{7056} = 84$. The value $72$ results from subtracting the lengths directly ($85 - 13 = 72$) instead of using the Pythagorean theorem. The value $82$ comes from an arithmetic slip when computing $\\sqrt{7056}$, such as a calculator misentry. The value $\\sqrt{7394}$ results from adding $85^2 + 13^2 = 7225 + 169 = 7394$ instead of subtracting, applying the formula as though the known leg were the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GMWVWM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $41$ units. What is the length of the arc intercepted by a central angle of $72^\\circ$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{41\\pi}{5}$"},{"key":"B","text":"$82\\pi$"},{"key":"C","text":"$\\frac{82\\pi}{5}$"},{"key":"D","text":"$\\frac{1681\\pi}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct arc length is $\\frac{82\\pi}{5}$. Arc length equals $\\frac{\\theta}{360} \\times 2\\pi r$. Substituting gives $\\frac{72}{360} \\times 2\\pi(41) = \\frac{1}{5} \\times 82\\pi = \\frac{82\\pi}{5}$. The value $\\frac{41\\pi}{5}$ results from using $\\pi r$ instead of $2\\pi r$ in the circumference, omitting the factor of $2$. The value $82\\pi$ results from computing the full circumference $2\\pi(41) = 82\\pi$ without applying the fractional portion $\\frac{72}{360}$. The value $\\frac{1681\\pi}{5}$ comes from using the sector area formula $\\frac{\\theta}{360} \\times \\pi r^2 = \\frac{1}{5} \\times 1681\\pi$ instead of the arc length formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GP9AQI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ is on side $\\overline{AB}$ and point $E$ is on side $\\overline{AC}$ such that $\\overline{DE}$ is parallel to $\\overline{BC}$. If $AD = 6$, $DB = 10$, and $DE = 9$, what is the length of $\\overline{BC}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24', ARRAY['24'], E'The correct answer is $24$. Since $\\overline{DE}$ is parallel to $\\overline{BC}$, triangles $ADE$ and $ABC$ are similar by the AA similarity criterion. The ratio of corresponding sides equals $\\frac{AD}{AB} = \\frac{6}{6 + 10} = \\frac{6}{16} = \\frac{3}{8}$. Therefore $\\frac{DE}{BC} = \\frac{3}{8}$, which gives $BC = 9 \\times \\frac{8}{3} = 24$. A common error is using the ratio $\\frac{AD}{DB} = \\frac{6}{10} = \\frac{3}{5}$ instead of $\\frac{AD}{AB} = \\frac{3}{8}$, which would incorrectly yield $BC = 9 \\times \\frac{5}{3} = 15$. Another error is applying the ratio in the wrong direction, computing $9 \\times \\frac{3}{8} = 3.375$ instead of dividing.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
