INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTB0C0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist wants to determine whether drinking green tea causes a reduction in blood pressure. The nutritionist asks $80$ volunteers to drink green tea daily for $6$ weeks and then measures their blood pressure. No control group is included. Which of the following is a valid conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Any observed reduction in blood pressure was caused by drinking green tea."},{"key":"B","text":"The study shows that green tea has no effect on blood pressure."},{"key":"C","text":"The study cannot establish that drinking green tea caused any observed change in blood pressure."},{"key":"D","text":"Because volunteers were used, the results apply to all adults."}]$lyceon_json$::jsonb, 'C', NULL, E'Without a control group, any observed change in blood pressure cannot be attributed to the green tea, because other factors such as the placebo effect, seasonal variation, or lifestyle changes could account for the results. The claim that any reduction was caused by the green tea incorrectly infers causation without a control group to isolate the effect. The claim that green tea has no effect goes beyond what the study can determine — the absence of a control group means no causal conclusion can be drawn in either direction. The claim that results apply to all adults overgeneralizes from a volunteer sample, which is not randomly selected from any defined population.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I6TAGM', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$7x - 4y = 5$$ $$3x + 2y = 17$$ What is the value of $3x + y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$13$"},{"key":"C","text":"$17$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying the second equation by $2$ gives $6x + 4y = 34$. Adding this to the first equation eliminates $y$: $(7x - 4y) + (6x + 4y) = 5 + 34$, so $13x = 39$ and $x = 3$. Substituting into $3(3) + 2y = 17$ gives $2y = 8$, so $y = 4$. Therefore $3x + y = 3(3) + 4 = 13$. The value $7$ results from computing $x + y = 3 + 4$ instead of $3x + y$, solving correctly but evaluating the wrong expression. The value $17$ comes from confusing the right-hand side of the second equation with the requested quantity. The value $1$ arises from a sign error when computing $3(3) - 4 \\cdot 2 = 9 - 8 = 1$, incorrectly subtracting $2y$ instead of adding $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IDG94P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 + 7x - 18$ and $y = 2x + 6$ intersect at two points. What is the sum of the $y$-coordinates of these two points of intersection?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$2$"},{"key":"C","text":"$12$"},{"key":"D","text":"$-22$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the two expressions equal: $x^2 + 7x - 18 = 2x + 6$, which simplifies to $x^2 + 5x - 24 = 0$. Factoring gives $(x + 8)(x - 3) = 0$, so $x = -8$ or $x = 3$. Substituting into $y = 2x + 6$: when $x = -8$, $y = -10$; when $x = 3$, $y = 12$. The sum of the $y$-coordinates is $-10 + 12 = 2$. The distractor $-5$ comes from computing the sum of the $x$-coordinates ($-8 + 3 = -5$) instead of the $y$-coordinates. The distractor $12$ results from finding only one intersection point and reporting its $y$-value. The distractor $-22$ results from a sign error, computing $-10 - 12 = -22$ instead of $-10 + 12 = 2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1VFIY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A parallelogram has a base of $29$ centimeters and a height of $13$ centimeters. What is the area of the parallelogram, in square centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '377', ARRAY['377'], E'The correct answer is $377$. The area of a parallelogram is base times height: $29 \\times 13 = 377$ square centimeters. A common error is computing $\\frac{1}{2}(29)(13) = 188.5$, confusing the parallelogram area formula with the triangle area formula. Another error is computing the perimeter ($2 \\times 29 + 2 \\times 13 = 84$) instead of the area.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6F8XN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are the solutions to the equation $\\sqrt{8x - 7} = x - 2$?', NULL, $lyceon_json$[{"key":"A","text":"$1$ only"},{"key":"B","text":"$11$ only"},{"key":"C","text":"$1$ and $11$"},{"key":"D","text":"$-11$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $8x - 7 = (x - 2)^2 = x^2 - 4x + 4$. Rearranging: $x^2 - 12x + 11 = 0$, which factors as $(x - 1)(x - 11) = 0$, yielding $x = 1$ or $x = 11$. Both must be checked in the original equation. For $x = 1$: $\\sqrt{8(1) - 7} = \\sqrt{1} = 1$ but $1 - 2 = -1$, so $1 \\neq -1$ and $x = 1$ is extraneous. For $x = 11$: $\\sqrt{8(11) - 7} = \\sqrt{81} = 9$ and $11 - 2 = 9$, which checks. The only valid solution is $11$. The distractor stating $1$ only is the extraneous root that fails because the right side is negative. The distractor stating both $1$ and $11$ results from solving the quadratic correctly but failing to check for extraneous solutions introduced by squaring. The distractor $-11$ results from a sign error when solving $x - 11 = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K9GOE8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A student is ordering custom stickers for a fundraiser. Each sticker costs $11$ dollars and there is a flat delivery fee of $8$ dollars. If the student has at most $85$ dollars to spend, what is the greatest number of stickers the student can order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Let $n$ represent the number of stickers. The total cost is $11n + 8$, and this must satisfy $11n + 8 \\leq 85$. Subtracting $8$ from both sides gives $11n \\leq 77$. Dividing both sides by $11$ gives $n \\leq 7$. Since $n$ must be a whole number, the greatest number of stickers is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KT673V', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A storage silo initially holds 1,130 pounds of grain. Grain is dispensed from the silo at a constant rate of 37 pounds per day. Which function $h(d)$ gives the amount of grain, in pounds, remaining in the silo $d$ days after dispensing begins?', NULL, $lyceon_json$[{"key":"A","text":"$h(d) = 1130 + 37d$"},{"key":"B","text":"$h(d) = 37d - 1130$"},{"key":"C","text":"$h(d) = 1130 - 37d$"},{"key":"D","text":"$h(d) = 1130 - \\frac{d}{37}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The silo starts with 1,130 pounds and loses 37 pounds each day, so the amount remaining after $d$ days is $h(d) = 1130 - 37d$. The expression $1130 + 37d$ incorrectly adds grain over time instead of subtracting, a sign error that ignores the dispensing. The expression $37d - 1130$ reverses the roles of the initial amount and the rate term, producing negative values almost immediately. The expression $1130 - \\frac{d}{37}$ uses the reciprocal of the rate, confusing 37 pounds per day with 1 pound every 37 days.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LFLI55', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A public health agency randomly selects $450$ adults from a city and records each person''s average daily screen time and their self-reported sleep quality rating (on a scale from $1$ to $10$). The agency finds that adults with more than $6$ hours of daily screen time have lower average sleep quality ratings than adults with fewer than $2$ hours of daily screen time. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"Reducing screen time causes improved sleep quality among adults in this city."},{"key":"B","text":"There is an association between daily screen time and sleep quality among adults in this city."},{"key":"C","text":"There is an association between daily screen time and sleep quality among all adults."},{"key":"D","text":"High screen time causes poor sleep quality among all adults."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because screen time was not randomly assigned to participants. Without random assignment, the study can establish an association but not causation. Since the sample was randomly selected from the city, the finding generalizes to adults in that city but not to all adults everywhere. The claim that reducing screen time causes improved sleep quality incorrectly infers causation from an observational design. The claim of association among all adults correctly avoids causation but overgeneralizes beyond the city population from which the sample was drawn. The claim that high screen time causes poor sleep among all adults both infers causation and overgeneralizes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M470I8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, the measure of angle $A$ is $(4x + 3)^\\circ$ and the measure of angle $B$ is $(7x - 8)^\\circ$. If the exterior angle at vertex $C$ measures $138^\\circ$, what is the measure of angle $A$?', NULL, $lyceon_json$[{"key":"A","text":"$55^\\circ$"},{"key":"B","text":"$83^\\circ$"},{"key":"C","text":"$42^\\circ$"},{"key":"D","text":"$13^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct measure of angle $A$ is $55^\\circ$. By the exterior angle theorem, the exterior angle at $C$ equals the sum of the two non-adjacent interior angles: $(4x + 3) + (7x - 8) = 138$. Simplifying gives $11x - 5 = 138$, so $11x = 143$ and $x = 13$. Then angle $A = 4(13) + 3 = 55^\\circ$. The value $83^\\circ$ results from correctly finding $x = 13$ but then computing angle $B = 7(13) - 8 = 83$ instead of angle $A$. The value $42^\\circ$ results from finding the interior angle at $C$ ($180 - 138 = 42$) rather than angle $A$, misreading what the question asks. The value $13^\\circ$ comes from reporting the value of $x$ itself instead of substituting back into the expression for angle $A$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NS1IZQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{5(3x + 11)}{7} = 20\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/3', ARRAY['17/3', '5.666', '5.667'], E'Multiply both sides by $7$ to get $5(3x + 11) = 140$. Distribute the $5$ to get $15x + 55 = 140$. Subtract $55$ from both sides: $15x = 85$. Divide by $15$: $x = \\frac{85}{15} = \\frac{17}{3}$. A common error is forgetting to distribute the $5$, solving $3x + 11 = 28$ to get $x = \\frac{17}{3}$, which coincidentally yields the same value. Another error is misapplying the multiplication by $7$ to only part of the numerator.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O65B0U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A company surveyed $250$ customers about their preferred delivery method (standard or express) and their membership status (member or non-member). Of the $250$ customers, $98$ are members and $152$ are non-members. Among members, $61$ prefer express delivery. Among non-members, $47$ prefer express delivery. If a customer is selected at random from those who prefer standard delivery, what is the probability that the customer is a member?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{37}{142}$"},{"key":"B","text":"$\\frac{37}{250}$"},{"key":"C","text":"$\\frac{37}{98}$"},{"key":"D","text":"$\\frac{105}{142}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Members who prefer standard delivery number $98 - 61 = 37$. Non-members who prefer standard delivery number $152 - 47 = 105$. The total number of standard-delivery customers is $37 + 105 = 142$. The conditional probability that a standard-delivery customer is a member is $\\frac{37}{142}$. The value $\\frac{37}{250}$ incorrectly uses the total number of customers as the denominator instead of conditioning on standard delivery. The value $\\frac{37}{98}$ divides by the total number of members rather than the total number of standard-delivery customers. The value $\\frac{105}{142}$ gives the probability that a standard-delivery customer is a non-member, answering the reverse of what was asked.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P9E88U', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7(2x^2 - 3x + 5) - 4(3x^2 + x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$26x^2 - 25x + 71$"},{"key":"B","text":"$2x^2 - 17x + 71$"},{"key":"C","text":"$2x^2 - 25x - 1$"},{"key":"D","text":"$2x^2 - 25x + 71$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing the first term gives $14x^2 - 21x + 35$. Distributing the second term gives $-12x^2 - 4x + 36$. Combining like terms: $(14 - 12)x^2 = 2x^2$, $(-21 - 4)x = -25x$, and $35 + 36 = 71$. The result is $2x^2 - 25x + 71$. The distractor $26x^2 - 25x + 71$ comes from adding the $x^2$ coefficients as $14 + 12 = 26$ instead of subtracting. The distractor $2x^2 - 17x + 71$ results from a sign error when distributing $-4$ to $x$, yielding $+4x$ instead of $-4x$, so $-21 + 4 = -17$. The distractor $2x^2 - 25x - 1$ results from an arithmetic slip on the constants, computing $35 - 36 = -1$ instead of $35 + 36 = 71$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PDE2E4', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 17x - 53$. What is the value of $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-66$"},{"key":"B","text":"$-29$"},{"key":"C","text":"$66$"},{"key":"D","text":"$172$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 7$ gives $g(7) = 17(7) - 53 = 119 - 53 = 66$. The value $-66$ results from a sign error, negating the correct answer. The value $-29$ results from an arithmetic slip of adding $17 + 7 = 24$ instead of multiplying $17 \\times 7 = 119$, then computing $24 - 53 = -29$. The value $172$ comes from adding $53$ instead of subtracting it, giving $119 + 53 = 172$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QUAF9Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has an area of $484\\pi$ square inches. What is the diameter of the circle, in inches?', NULL, $lyceon_json$[{"key":"A","text":"$44$"},{"key":"B","text":"$22$"},{"key":"C","text":"$242$"},{"key":"D","text":"$484$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct diameter is $44$ inches. Using the area formula $A = \\pi r^2$, setting $\\pi r^2 = 484\\pi$ gives $r^2 = 484$, so $r = 22$. The diameter is $2r = 44$. The value $22$ results from finding the radius but stopping before doubling to get the diameter. The value $242$ comes from dividing $484$ by $2$ instead of taking the square root, incorrectly setting up the equation as $2r = 484$. The value $484$ results from reporting the numerical coefficient of the area rather than computing the radius and diameter.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QVUVV2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $15$ values has a mean of $62$ and a median of $58$. The largest value in the data set, which is $97$, is replaced by $127$. Which of the following correctly describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases by $2$ and the median stays the same."},{"key":"B","text":"Both the mean and median increase by $2$."},{"key":"C","text":"The mean increases by $2$ and the median increases by $30$."},{"key":"D","text":"Both the mean and median stay the same."}]$lyceon_json$::jsonb, 'A', NULL, E'Replacing $97$ with $127$ increases the sum by $127 - 97 = 30$. The original sum is $15 \\times 62 = 930$, and the new sum is $960$. The new mean is $\\frac{960}{15} = 64$, an increase of $2$. The median is the $8$th value in the ordered list. Since $97$ was the largest value and was replaced by an even larger value ($127$), the $8$th value in the ordered list is unchanged, so the median remains $58$. The claim that both the mean and median increase by $2$ incorrectly assumes that changing the largest value affects the middle of the distribution. The claim that the median increases by $30$ confuses the change in the replaced value with a shift in the median. The claim that both stay the same fails to account for the effect on the sum and therefore the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXSAVI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 11x + 28}{x^2 - 49} \\cdot \\frac{x + 7}{x - 2}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 4}{x - 2}$"},{"key":"B","text":"$\\frac{x + 4}{x + 2}$"},{"key":"C","text":"$\\frac{x - 4}{x + 7}$"},{"key":"D","text":"$\\frac{x - 7}{x - 2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $x^2 - 11x + 28 = (x - 4)(x - 7)$ and $x^2 - 49 = (x - 7)(x + 7)$. The expression becomes $\\frac{(x - 4)(x - 7)}{(x - 7)(x + 7)} \\cdot \\frac{x + 7}{x - 2}$. Cancel $(x - 7)$ in the first fraction, then cancel $(x + 7)$ across the product, yielding $\\frac{x - 4}{x - 2}$. The distractor $\\frac{x + 4}{x + 2}$ results from sign errors in factoring, flipping the signs within both remaining binomials. The distractor $\\frac{x - 4}{x + 7}$ comes from cancelling only $(x - 7)$ without proceeding to multiply by $\\frac{x + 7}{x - 2}$. The distractor $\\frac{x - 7}{x - 2}$ reflects incorrectly cancelling $(x - 4)$ with $(x + 7)$ while retaining the wrong numerator factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S7HAO9', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $13x + 47 = 151$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\frac{151}{13}$"},{"key":"D","text":"$198$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting $47$ from both sides gives $13x = 104$, and dividing both sides by $13$ gives $x = 8$. The value $-8$ results from a sign error, negating the correct answer. The value $\\frac{151}{13}$ results from dividing $151$ by $13$ directly without first subtracting $47$, treating the equation as $13x = 151$. The value $198$ results from adding $47$ to $151$ to get $13x = 198$ and then reporting $198$ as the answer without dividing by $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SCUTIG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A bakery produces muffins and loaves of bread each day. Each muffin requires $2$ hours of labor and $3$ kilograms of flour. Each loaf requires $4$ hours of labor and $5$ kilograms of flour. The bakery has at most $38$ hours of labor and at most $49$ kilograms of flour available per day. If the bakery produces $7$ muffins in a day, what is the maximum number of whole loaves it can produce that same day?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $t$ be the number of loaves. The labor constraint is $2(7) + 4t \\leq 38$, which simplifies to $14 + 4t \\leq 38$, giving $4t \\leq 24$, so $t \\leq 6$. The flour constraint is $3(7) + 5t \\leq 49$, which simplifies to $21 + 5t \\leq 49$, giving $5t \\leq 28$, so $t \\leq 5.6$. Since both constraints must hold simultaneously and $t$ must be a whole number, the maximum is $5$. The value $6$ satisfies the labor constraint but violates the flour constraint, since $21 + 5(6) = 51 > 49$, reflecting an arithmetic slip in checking the flour bound. The value $7$ comes from using only the labor constraint and ignoring the flour constraint entirely. The value $9$ comes from dividing the total flour by the per-loaf flour requirement ($49 \\div 5 \\approx 9.8$), ignoring the flour already consumed by the muffins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SDDW45', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $350$ households in a city with $8{,}400$ households and finds that $29\\%$ of the sample have installed solar panels. The margin of error for the survey is $\\pm 4.9$ percentage points. Based on this information, which of the following is a plausible estimate for the number of households in the entire city that have installed solar panels?', NULL, $lyceon_json$[{"key":"A","text":"$1{,}680$"},{"key":"B","text":"$2{,}024$"},{"key":"C","text":"$2{,}436$"},{"key":"D","text":"$3{,}108$"}]$lyceon_json$::jsonb, 'C', NULL, E'The plausible range for the population proportion is $29\\% \\pm 4.9\\%$, which is $24.1\\%$ to $33.9\\%$. Applying this to $8{,}400$ households gives a range of $0.241 \\times 8{,}400 = 2{,}024.4$ to $0.339 \\times 8{,}400 = 2{,}847.6$. The value $2{,}436$ equals $0.29 \\times 8{,}400$ and falls within this interval, making it plausible. The value $1{,}680$ equals $0.20 \\times 8{,}400$, which is below the lower bound and outside the confidence interval. The value $2{,}024$ is approximately the lower bound but falls just below it at $24.1\\%$, and more precisely results from rounding $0.241 \\times 8{,}400$ down. The value $3{,}108$ equals $0.37 \\times 8{,}400$, which exceeds the upper bound of $33.9\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SI1Z00', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A data analyst models the relationship between advertising spending in thousands of dollars, $x$, and monthly revenue in thousands of dollars, $y$, with the equation $y = 4.6x + 29$. At an advertising spending of $17$ thousand dollars, the observed revenue is $103.4$ thousand dollars. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-3.8$"},{"key":"B","text":"$3.8$"},{"key":"C","text":"$-107.2$"},{"key":"D","text":"$107.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted revenue at $x = 17$ is $y = 4.6(17) + 29 = 78.2 + 29 = 107.2$ thousand dollars. The residual is defined as observed minus predicted: $103.4 - 107.2 = -3.8$. A negative residual indicates the model overpredicted the revenue at this spending level. The value $3.8$ results from computing predicted minus observed ($107.2 - 103.4$), reversing the residual formula and getting the wrong sign. The value $-107.2$ arises from subtracting the predicted value from zero instead of from the observed value. The value $107.2$ is the predicted value itself, not the residual, reflecting a failure to compute the difference between observed and predicted values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMRKC8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = (x + 11)^2 - 13$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-13', ARRAY['-13'], E'The function $g(x) = (x + 11)^2 - 13$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = -11$, and $k = -13$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value is $k = -13$, occurring at $x = -11$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U9J1NO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $29^\\circ$ and the hypotenuse has length $37$. What is the length of the leg opposite the $29^\\circ$ angle, to the nearest tenth? (Use $\\sin 29^\\circ \\approx 0.4848$ and $\\cos 29^\\circ \\approx 0.8746$.)', NULL, $lyceon_json$[{"key":"A","text":"$17.9$"},{"key":"B","text":"$20.5$"},{"key":"C","text":"$32.4$"},{"key":"D","text":"$76.3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct length is $17.9$. The leg opposite the $29^\\circ$ angle is found using the sine ratio: $\\text{opposite} = \\text{hypotenuse} \\times \\sin 29^\\circ = 37 \\times 0.4848 = 17.9376$, which rounds to $17.9$. The value $20.5$ results from using the tangent ratio instead of sine (computing $37 \\times 0.5543 \\approx 20.5$ with $\\tan 29^\\circ \\approx 0.5543$), setting up the equation incorrectly. The value $32.4$ comes from using cosine instead of sine ($37 \\times 0.8746 \\approx 32.4$), confusing the adjacent side with the opposite side. The value $76.3$ results from dividing the hypotenuse by sine ($37 / 0.4848 \\approx 76.3$) rather than multiplying, as if the given side were the opposite leg rather than the hypotenuse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UD15B5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 - 3x - 88 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Factor the quadratic: $x^2 - 3x - 88 = (x - 11)(x + 8) = 0$. Setting each factor to zero gives $x = 11$ or $x = -8$. Since the problem requires $x > 0$, the answer is $11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V986T1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $13$ identical parts every $4$ minutes. At this constant rate, how many parts does the factory produce in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$33$"},{"key":"B","text":"$52$"},{"key":"C","text":"$65$"},{"key":"D","text":"$260$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{13 \\text{ parts}}{4 \\text{ minutes}}$. In $20$ minutes, the number of parts produced is $\\frac{13}{4} \\times 20 = \\frac{260}{4} = 65$. The value $33$ results from an arithmetic slip such as computing $13 \\times 2 + 7 = 33$ instead of correctly scaling. The value $52$ comes from multiplying $13 \\times 4 = 52$, confusing the rate denominator with a multiplier. The value $260$ results from computing $13 \\times 20 = 260$ without dividing by $4$, ignoring that $13$ parts are produced per $4$ minutes, not per $1$ minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBU6XA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A city''s population increased by $12\\%$ from $2020$ to $2023$. If the population in $2023$ was $52{,}640$, what was the population in $2020$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47000', ARRAY['47000'], E'Let the population in $2020$ be $p$. After a $12\\%$ increase, the population is $1.12p$. Setting $1.12p = 52{,}640$ gives $p = \\frac{52{,}640}{1.12} = 47{,}000$. A common error is to subtract $12\\%$ of $52{,}640$ from $52{,}640$: $52{,}640 \\times 0.12 = 6{,}316.8$, giving $52{,}640 - 6{,}316.8 = 46{,}323.2$, which incorrectly applies the percentage to the final value rather than the original. Another error is to divide by $0.12$ instead of $1.12$, which yields an unreasonably large number.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YQQOSL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'In the equation $11x - 4y = 53$, if $x = 7$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Substituting $x = 7$ gives $11(7) - 4y = 53$, which simplifies to $77 - 4y = 53$. Subtracting $77$ from both sides yields $-4y = -24$, and dividing by $-4$ gives $y = 6$. A common error is a sign mistake when isolating $y$, such as obtaining $y = -6$ by dividing $-24$ by $4$ instead of $-4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZRIS7S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'The line of best fit for a data set is given by $y = 3.7x + 8.4$. What is the predicted value of $y$ when $x = 6$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30.6', ARRAY['153/5', '30.6'], E'Substituting $x = 6$ into the equation gives $y = 3.7(6) + 8.4 = 22.2 + 8.4 = 30.6$. A common error is to forget the $y$-intercept, giving $22.2$ alone. Another error is to add $3.7 + 6 + 8.4 = 18.1$ instead of multiplying the slope by $x$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20CFIY1', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Entomologist Priya Venkatesh recently documented an unusual behavior in carpenter ants living near geothermal vents in Iceland. Unlike most carpenter ant populations, which excavate nesting galleries in dead wood, these Icelandic colonies construct their nests in compacted volcanic soil warmed by subterranean heat. Venkatesh observed that the geothermally heated soil maintains a stable temperature of roughly 27 degrees Celsius year-round, eliminating the need for the seasonal dormancy that carpenter ants in colder regions typically undergo. As a result, the Icelandic colonies remain active and reproduce continuously, yielding colony sizes approximately three times larger than those of comparable populations in Scandinavia.', $lyceon_json$[{"key":"A","text":"Carpenter ants near Icelandic geothermal vents nest in warm volcanic soil, enabling year-round activity and unusually large colonies."},{"key":"B","text":"Geothermal vents in Iceland are home to a wider variety of insect species than previously recognized."},{"key":"C","text":"Carpenter ants in Scandinavia are unable to survive without entering seasonal dormancy."},{"key":"D","text":"Volcanic soil is a superior nesting material for all ant species compared to dead wood."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage focuses on how Icelandic carpenter ants exploit geothermally warmed volcanic soil for nesting, which allows them to skip dormancy and grow larger colonies. The choice about warm volcanic soil enabling year-round activity and large colonies captures this central idea. The claim about a wider variety of insect species near geothermal vents goes beyond the passage, which discusses only carpenter ants. The assertion that Scandinavian carpenter ants cannot survive without dormancy misreads the passage, which states they typically undergo dormancy but does not claim they would die without it. The generalization that volcanic soil is superior for all ant species extrapolates far beyond the specific finding about one carpenter ant population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20LIFQY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Keiko Taniguchi has found that populations of the nudibranch Chromodoris willani in the Coral Triangle rely on chemical defenses absorbed from the sponges they consume. ______ Taniguchi recommends that conservation efforts prioritize protecting sponge habitats alongside nudibranch populations.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence presents a recommendation that follows logically from the dependence described in the first sentence: because nudibranchs rely on sponges for chemical defenses, conservation should protect sponge habitats. The transition "Accordingly" correctly signals this cause-to-recommendation relationship. The option suggesting contrast ("In contrast") implies an opposition between the two sentences, but no opposition exists. The option "For instance" would indicate that the second sentence is a specific example of the first, yet a conservation recommendation is not an example of a biological dependency. The option "On the other hand" suggests an alternative perspective, but the second sentence builds on rather than diverges from the first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24DBAOW', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'After the prolonged civil dispute over water rights, the neighboring townships finally reached a ______ agreement that allocated irrigation access based on acreage under cultivation rather than historical precedent.', $lyceon_json$[{"key":"A","text":"pragmatic"},{"key":"B","text":"theatrical"},{"key":"C","text":"redundant"},{"key":"D","text":"corrosive"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an agreement that resolved a prolonged dispute by allocating water based on a practical metric (acreage under cultivation). The word meaning guided by practical considerations rather than theory fits this context precisely. The word meaning exaggerated or dramatic in manner describes performative behavior, which is unrelated to the nature of a resource-sharing agreement. The word meaning unnecessary or superfluous describes excess, not a practical approach to resolving a dispute. The word meaning causing gradual destruction describes a damaging quality, which contradicts the passage''s depiction of a constructive resolution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24OLS3H', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the forensic accountants gained access to the offshore holding company''s ledgers in March of 2019, a pattern of systematic invoice falsification ______ the firm''s reported earnings by nearly forty-seven million euros over the preceding nine fiscal quarters.', $lyceon_json$[{"key":"A","text":"had inflated"},{"key":"B","text":"has inflated"},{"key":"C","text":"was inflating"},{"key":"D","text":"inflated"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction ''by the time [past event]'' establishes a temporal sequence requiring the past perfect tense to indicate that one action was completed before another past action occurred. The inflation of earnings was already complete before the accountants gained access, so the past perfect ''had inflated'' is the correct form. The present perfect ''has inflated'' is inappropriate because the entire context is anchored in the past (''gained access,'' ''March of 2019''), and the present perfect links a past event to the present moment. The past progressive ''was inflating'' implies the falsification was still ongoing at the moment of access, but the phrase ''over the preceding nine fiscal quarters'' and the specific cumulative total indicate a completed action. The simple past ''inflated'' fails to convey the completed-before-access sequence that ''by the time'' demands in Standard English.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24Z55ZZ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW254K5PO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The provincial legislature has required that every licensed aquaculture operation along the estuary ______ a continuous water-quality monitoring system capable of detecting seventeen distinct chemical pollutants, a stipulation that industry representatives contend will raise operating costs by nearly thirty percent.', $lyceon_json$[{"key":"A","text":"installs"},{"key":"B","text":"install"},{"key":"C","text":"will install"},{"key":"D","text":"would install"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb ''required'' triggers the mandative subjunctive in the ''that'' clause that follows it. In Standard English, verbs of demand, requirement, and insistence take the subjunctive mood, which uses the bare infinitive (base form) of the verb regardless of the subject''s number. Although ''every licensed aquaculture operation'' is grammatically singular and would ordinarily take the indicative ''installs,'' the subjunctive requires the uninflected base form ''install.'' The option using ''will install'' incorrectly inserts a future-tense auxiliary into the subjunctive construction, which is not permitted in Standard English after verbs of requirement. The option using ''would install'' introduces conditionality, suggesting the requirement is hypothetical rather than enacted, which contradicts the definitive meaning of ''has required.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2561M55', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planner Dagny Kristjansdottir has demonstrated that Reykjavik''s 2017 geothermal district heating expansion reduced household carbon emissions by an estimated 19 percent within its service zone. ______ Kristjansdottir''s own longitudinal data show that total citywide emissions remained essentially flat over the same period, as residents who saved on heating costs used the surplus income to increase automobile travel and air-conditioned retail consumption, offsetting much of the anticipated environmental gain.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"Nonetheless,"},{"key":"C","text":"To this end,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence reports a positive result (reduced household emissions), while the second sentence reveals that this gain was neutralized at the citywide level by offsetting behavior. The transition "Nonetheless" correctly signals that the second finding stands in concessive tension with the first: the expected benefit occurred locally but did not translate into the broader outcome. The option "In fact" typically intensifies or confirms a preceding claim, but the second sentence complicates rather than reinforces the first; choosing it would misrepresent the relationship as emphatic agreement. The option "To this end" implies the second sentence describes an action taken to achieve the goal mentioned in the first, yet the second sentence reports an unintended consequence, not a purposeful measure. The option "For example" implies the second sentence illustrates the first, but flat citywide emissions are not an instance of reduced household emissions; they represent a contrasting outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26HJ164', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Tomoko Arai has reexamined the role of itinerant puppet theaters in seventeenth-century rural Japan. While previous scholarship treated these troupes primarily as entertainment providers, Arai argues that they served a critical informational function in communities with limited literacy. Troupe leaders adapted their performances to incorporate news of regional tax policies, crop failures in neighboring provinces, and edicts from domain lords, embedding this information within familiar folk narratives. Arai found evidence in merchant diaries that villages frequently adjusted planting decisions and grain storage practices in the weeks following a troupe''s visit. She contends that dismissing these performances as mere amusement obscures their significance as an informal information network that shaped economic behavior in communities otherwise isolated from official channels of communication.', $lyceon_json$[{"key":"A","text":"Itinerant puppet theaters in seventeenth-century rural Japan functioned as informal information networks that influenced villagers' economic decisions."},{"key":"B","text":"Puppet theater troupes in seventeenth-century Japan were more artistically sophisticated than scholars have previously acknowledged."},{"key":"C","text":"Rural Japanese villages in the seventeenth century had no access to official government communications about tax policy."},{"key":"D","text":"Merchant diaries are the most reliable primary sources for understanding rural economic practices in seventeenth-century Japan."}]$lyceon_json$::jsonb, 'A', NULL, E'Arai''s central argument is that puppet theaters were not merely entertainment but informal information networks that conveyed news and influenced economic behavior such as planting and grain storage decisions. The choice identifying puppet theaters as information networks shaping economic decisions captures this main idea. The claim about artistic sophistication addresses an aspect of the troupes that the passage never discusses; Arai''s argument concerns their informational function, not their aesthetic quality. The assertion that villages had no access to official communications overstates the passage, which says communities were otherwise isolated from official channels, not that they had zero access. The claim about merchant diaries being the most reliable primary sources focuses on a methodological detail Arai used as supporting evidence rather than on her central argument about the theaters'' role.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26QAHH8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding would most directly undermine the explanation proposed by Mafabi and Sundaram?', E'Environmental scientists Mafabi and Sundaram studied mercury concentrations in freshwater mussels across 31 rivers in Southeast Asia. They found that mussels downstream of artisanal gold mining operations contained mercury levels seven to twelve times higher than mussels upstream of the same operations. Mafabi and Sundaram concluded that runoff from gold mining is the dominant source of mercury accumulation in these mussel populations, reasoning that the sharp upstream-to-downstream gradient within individual rivers points to a localized, mine-related source rather than atmospheric deposition, which would affect upstream and downstream sites more uniformly.', $lyceon_json$[{"key":"A","text":"Rivers without any gold mining operations in their watersheds showed similar upstream-to-downstream mercury gradients in mussel tissue, attributable to naturally occurring mercury-rich geological formations downstream."},{"key":"B","text":"Artisanal gold miners in the studied regions have recently begun using gravity separation methods that do not involve mercury."},{"key":"C","text":"Mercury concentrations in river sediment were consistently higher near mining sites than at points farther downstream."},{"key":"D","text":"Mussels upstream of mining operations in the studied rivers had mercury levels comparable to mussels in rivers with no mining activity."}]$lyceon_json$::jsonb, 'A', NULL, E'Mafabi and Sundaram''s explanation depends on the upstream-to-downstream mercury gradient being attributable specifically to mining runoff. If rivers with no mining operations at all showed similar gradients due to naturally mercury-rich geology downstream, the gradient could not be uniquely attributed to mining, directly undermining their conclusion. The finding about miners adopting mercury-free methods addresses future mining practices but does not challenge the explanation for mercury already measured in the study''s mussel populations. The finding that sediment mercury is highest near mining sites would reinforce rather than undermine the mining-runoff explanation. The finding that upstream mussels match mercury levels in mining-free rivers would support the authors'' reasoning by confirming that elevated levels appear only downstream of mines.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27G04KW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Renata Szabo analyzed the rehearsal notebooks of 83 professional orchestral cellists across Central Europe and found that cellists who practiced difficult passages at a tempo 35 to 50 percent slower than the performance tempo for at least four sessions before attempting full-speed play made significantly fewer errors during concert performances than cellists who began practicing at or near performance tempo from the outset. Szabo argues that slow practice allows cellists to encode precise motor patterns before speed introduces the potential for inaccuracy. If Szabo''s interpretation is correct, one would expect that cellists who practiced difficult passages at a tempo only 10 to 15 percent below performance speed ________', $lyceon_json$[{"key":"A","text":"would make more concert errors than the slow-practice group but fewer than those who practiced at full tempo from the start."},{"key":"B","text":"would show error rates identical to those of cellists practicing at 35 to 50 percent below performance tempo."},{"key":"C","text":"would perform more expressively than either of the other groups due to maintaining closer contact with the musical phrasing."},{"key":"D","text":"would abandon the moderate-tempo approach and switch to full-speed practice after the first session."}]$lyceon_json$::jsonb, 'A', NULL, E'Szabo''s framework implies a relationship between practice tempo reduction and motor-pattern accuracy: slower practice produces better encoding. A moderate reduction of 10 to 15 percent would logically provide some encoding benefit but less than the 35 to 50 percent reduction, placing error rates between the two extremes. The prediction of identical error rates to the slow-practice group ignores the dose-dependent logic of Szabo''s argument, which ties greater tempo reduction to greater accuracy. The prediction about enhanced expressiveness introduces a dimension the passage never addresses; Szabo''s research concerns error rates, not musical expression. The prediction that cellists would abandon moderate-tempo practice after one session has no basis in the passage and introduces a behavioral assumption unsupported by the research.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW289LHF5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The viscosity of the polymer solutions stored in the seven refrigerated vats at the Glenmark processing facility ______ measurably whenever the ambient temperature in the warehouse rises above nineteen degrees Celsius.', $lyceon_json$[{"key":"A","text":"increases"},{"key":"B","text":"increase"},{"key":"C","text":"have increased"},{"key":"D","text":"are increasing"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the verb is the singular noun ''viscosity,'' not the plural nouns ''solutions'' or ''vats'' that appear in the intervening prepositional phrases. Because the subject is singular, the verb must also be singular. The adverb ''whenever'' signals a habitual, recurring condition, which requires the simple present tense. The base form ''increase'' lacks the third-person singular inflection needed to agree with ''viscosity.'' The option ''have increased'' pairs a plural auxiliary with a singular subject and uses the present perfect, which is inappropriate for describing a recurring conditional pattern. The option ''are increasing'' similarly uses a plural auxiliary and the progressive aspect, which describes an action in progress rather than a habitual occurrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW291SIA1', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how the author of Text 2 would most likely characterize the evidence presented in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B6SDSA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the recommendation in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BPR2W2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Harvested by hand during the brief alpine summer and dried on wooden racks at elevations above 2,700 ______ the aromatic petals of the Edelweiss-adjacent species Leontopodium nivale have long been used in traditional Swiss herbal tinctures.', $lyceon_json$[{"key":"A","text":"meters,"},{"key":"B","text":"meters."},{"key":"C","text":"meters;"},{"key":"D","text":"meters:"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with two participial phrases (''Harvested by hand during the brief alpine summer'' and ''dried on wooden racks at elevations above 2,700 meters'') that modify the subject ''the aromatic petals.'' A comma is the only appropriate punctuation to separate these introductory modifying phrases from the main clause they modify. A period after ''meters'' would strand the participial phrases as a fragment, since they contain no independent subject or finite verb. A semicolon requires independent clauses on both sides, but the participial phrases do not constitute an independent clause. A colon similarly demands a complete independent clause before it, which the participial phrases do not provide.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZQIO3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleoclimatologist Renata Szabo has used isotope ratios in Greenland ice cores to argue that the Younger Dryas cold period, which began approximately 12,900 years ago, was triggered by a sudden influx of glacial meltwater into the North Atlantic. ______ geochemist Tomoko Hasegawa contends that volcanic sulfate deposits in the same ice cores point to a series of eruptions in the Aleutian Arc as the more probable catalyst, noting that the meltwater hypothesis cannot account for the abrupt onset of cooling that the isotope data themselves reveal.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"That is,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence introduces a rival scientist who directly opposes Szabo''s meltwater hypothesis by offering an alternative volcanic explanation and criticizing the meltwater account''s explanatory power. The transition "On the contrary" correctly signals that the second claim contradicts the first. The option "In addition" implies the volcanic evidence supplements the meltwater hypothesis, but Hasegawa presents it as a competing explanation, not a complementary one. The option "That is" signals a restatement or clarification, yet Hasegawa is advancing a different causal claim rather than restating Szabo''s. The option "Granted" introduces a concession the speaker accepts before pivoting, but the passage does not frame Hasegawa as conceding Szabo''s point; she directly challenges it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CPM1QW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Concealed beneath nearly four meters of volcanic ash deposited during the catastrophic eruption of 1631 ______ a pair of extraordinarily intact frescoes depicting maritime trade routes that art historians believe were commissioned by a previously undocumented patron of the Neapolitan school.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"are"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'This sentence uses inverted word order: the participial phrase ''Concealed beneath nearly four meters of volcanic ash deposited during the catastrophic eruption of 1631'' precedes the verb, and the true subject ''a pair of extraordinarily intact frescoes'' follows it. In Standard English, ''a pair'' functions as a singular collective noun when the pair is considered as a single unit, so the verb must be singular. The context of an archaeological discovery calls for the past tense. The plural past ''were'' incorrectly treats ''pair'' as plural. The present tense ''are'' fails on tense, since the discovery event occurred in the past. The present perfect ''have been'' is likewise wrong in tense, using a form that connects a past event to the present moment, which does not suit a narrative describing a specific historical discovery.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D6NH2T', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'Neurobiologist Carla Shatz''s discovery that spontaneous electrical activity in the fetal retina shapes the wiring of the visual cortex before birth overturned the longstanding assumption that neural circuit formation depends entirely on sensory experience. Her work demonstrated that waves of electrical impulses sweep across the retina in utero, guiding the formation of precise topographic maps in the brain well before the eyes ever receive light.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DYYC5U', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from an art historian, if accurate, would most effectively support the researcher''s claim?', E'A graduate researcher argues in a dissertation chapter that the seventeenth-century Dutch painter Judith Leyster deliberately subverted the conventions of the merry company genre—scenes depicting festive groups drinking and making music—by centering her compositions on female figures who observe the revelry with expressions of critical detachment rather than participating joyfully. The researcher contends that this compositional strategy allowed Leyster to comment on the gendered power dynamics of Dutch social life within a genre that typically celebrated communal pleasure without interrogation.', $lyceon_json$[{"key":"A","text":"\"In Leyster's merry company scenes, the principal female figure consistently occupies a watchful, peripheral position, her gaze directed not at the viewer but at the male revelers, creating a visual tension absent from her male contemporaries' treatments of the same genre.\""},{"key":"B","text":"\"Leyster's technical handling of candlelight effects in her genre scenes rivals that of Gerrit van Honthorst, demonstrating her mastery of Caravaggist chiaroscuro techniques.\""},{"key":"C","text":"\"While Leyster's still-life paintings have received increasing scholarly attention, her genre scenes remain understudied relative to those of her husband, Jan Miense Molenaer.\""},{"key":"D","text":"\"Leyster's enrollment in the Haarlem Guild of Saint Luke in 1633 made her one of only two women admitted to the guild during that decade, a distinction that speaks to her professional standing.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The researcher claims Leyster subverted merry company conventions by centering critically detached female observers. The quotation describing a watchful female figure in a peripheral position whose gaze is directed at male revelers, creating visual tension absent from male painters'' versions, directly supports the claim about compositional subversion and gendered commentary. The quotation about Leyster''s candlelight technique addresses her technical skill in a different stylistic tradition and says nothing about her compositional treatment of gender. The quotation about her genre scenes being understudied comments on art-historical attention rather than on what Leyster''s compositions actually depict. The quotation about guild membership speaks to her professional status but not to how she composed her merry company paintings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E1DEXW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Honeybees communicate the location of food sources through a series of movements known as the waggle dance. [underlined: A forager returning from a clover patch three hundred meters to the northeast will perform a figure-eight pattern angled thirty degrees from vertical on the comb surface, waggling for approximately half a second during the straight run.] Other bees observing the dance can then fly directly to the indicated location without following the original forager.', $lyceon_json$[{"key":"A","text":"It illustrates the general claim about honeybee communication by describing a specific instance of the waggle dance."},{"key":"B","text":"It introduces a counterexample that complicates the initial claim about how bees locate food."},{"key":"C","text":"It explains why the waggle dance is more effective than other forms of insect communication."},{"key":"D","text":"It summarizes the main conclusion that the passage is building toward."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence provides a concrete example — a forager returning from a specific distance and direction performing particular movements — that directly demonstrates the general claim in the first sentence about bees using waggle dances to communicate food locations. The option about a counterexample contradicts the passage; the described dance supports rather than complicates the communication claim. The option about comparative effectiveness introduces a claim the passage never makes; the text describes how the dance works, not how it ranks against other insect communication. The option about summarizing the main conclusion misidentifies the sentence''s role; the conclusion about other bees flying to the location follows the underlined sentence rather than being summarized by it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HIWYEH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the botanists'' hypothesis?', E'Botanists at the Svalbard Research Station hypothesize that a recently observed northward expansion of dwarf willows on the Norwegian archipelago is driven primarily by rising soil temperatures rather than by changes in precipitation or sunlight duration. They note that average soil temperatures at 10-centimeter depth have increased by 1.9 degrees Celsius over the past fifteen years, while precipitation and daylight patterns have remained statistically unchanged.', $lyceon_json$[{"key":"A","text":"Dwarf willows transplanted to plots with artificially heated soil at a constant precipitation level grew 40 percent faster than those in unheated control plots."},{"key":"B","text":"Dwarf willow seeds require a specific duration of winter darkness to germinate successfully."},{"key":"C","text":"Precipitation on the archipelago has recently begun to shift from snow to rain during early spring months."},{"key":"D","text":"Several other Arctic shrub species have declined in population on the same archipelago over the past fifteen years."}]$lyceon_json$::jsonb, 'A', NULL, E'The botanists hypothesize that rising soil temperature is the primary driver of dwarf willow expansion. A controlled experiment showing that artificially heated soil accelerates willow growth while holding precipitation constant would directly isolate temperature as the causal factor. The finding about seed germination requiring winter darkness concerns a photoperiod requirement unrelated to the soil temperature hypothesis. The finding about precipitation shifting from snow to rain would introduce a precipitation change, potentially undermining the botanists'' claim that precipitation has remained unchanged rather than supporting the temperature hypothesis. The finding that other Arctic shrubs have declined does not address whether soil temperature drives dwarf willow expansion and could suggest alternative factors at work.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I0SSFV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The submersible''s titanium hull—engineered to withstand pressures exceeding 1,100 atmospheres at the deepest surveyed points of the Kermadec ______ allowed the research team to collect sediment cores from a biologically uncharted abyssal trench northeast of New Zealand.', $lyceon_json$[{"key":"A","text":"Trench, allowed"},{"key":"B","text":"Trench—allowed"},{"key":"C","text":"Trench; allowed"},{"key":"D","text":"Trench, it allowed"}]$lyceon_json$::jsonb, 'B', NULL, E'The parenthetical element ''engineered to withstand pressures exceeding 1,100 atmospheres at the deepest surveyed points of the Kermadec Trench'' is opened with a dash after ''hull.'' Punctuation symmetry requires a matching dash after ''Trench'' to close the parenthetical before the verb ''allowed.'' Using a comma to close a dash-opened parenthetical creates a mismatched pair, which is nonstandard. A semicolon would incorrectly split the subject ''hull'' from its predicate ''allowed,'' severing the main clause. Inserting ''it'' after a comma fails to close the dash-opened parenthetical and introduces a redundant pronoun, since ''the submersible''s titanium hull'' already serves as the subject of the main clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LV4X0Q', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief profile of Qanat irrigation systems for a geography newsletter. The student wants to explain to readers what a qanat is and how it functions. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N0C4PB', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Dimitri Volkov studied charitable giving patterns among 2,700 residents of mid-sized Russian cities and found that individuals who regularly attended community cultural events—such as local theater productions, library readings, and municipal art exhibitions—donated to local charities at nearly twice the rate of individuals who did not attend such events, even after controlling for income, education, and religious participation. Volkov proposes that community cultural events strengthen donors'' sense of civic identity by making local institutions and shared public spaces emotionally salient, thereby increasing willingness to support local causes. However, Volkov acknowledges a complication: residents who already feel strong civic attachment may be disproportionately drawn to cultural events in the first place. To address this concern, Volkov would need to demonstrate that ________', $lyceon_json$[{"key":"A","text":"individuals with initially low civic attachment who began attending cultural events subsequently increased their charitable giving, suggesting that attendance itself cultivates the civic identity that drives donations."},{"key":"B","text":"charitable giving rates among cultural-event attendees were consistent across all income levels in the study population."},{"key":"C","text":"residents of larger Russian cities attended cultural events at higher rates than residents of mid-sized cities."},{"key":"D","text":"individuals who attended cultural events in cities outside their own donated to charities in those other cities rather than in their home cities."}]$lyceon_json$::jsonb, 'A', NULL, E'Volkov''s complication is a selection effect: people with pre-existing civic attachment may self-select into cultural events, making it unclear whether attendance causes civic identity or merely correlates with it. To address this, he would need evidence that attendance changes people who start without strong civic attachment—showing that initially low-attachment individuals who begin attending events then increase giving would support a causal rather than merely correlational relationship. The finding about consistent giving across income levels addresses a potential income confound, which Volkov already controlled for, and does not resolve the selection problem of pre-existing civic identity. The finding about attendance rates in larger versus mid-sized cities introduces a geographic comparison irrelevant to the causal question about whether attendance itself strengthens civic identity. The finding about donating to other cities'' charities would test a different hypothesis about geographic loyalty rather than addressing whether cultural event attendance generates civic attachment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NMG63M', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The 17th-century Dutch merchant Pieter van Hoorn maintained that the East India Company''s monopoly on spice trading did not ______ competition but rather concentrated it among a smaller group of sanctioned traders who competed ruthlessly with one another for the most profitable routes.', $lyceon_json$[{"key":"A","text":"eliminate"},{"key":"B","text":"inaugurate"},{"key":"C","text":"replicate"},{"key":"D","text":"commemorate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts two views of the monopoly''s effect: the blank word describes what the monopoly did not do, while the second clause explains that competition was concentrated rather than removed. The word meaning to completely end or remove fits this contrast, since van Hoorn argues competition persisted in a different form. The word meaning to begin or formally launch implies starting something new, but the passage discusses whether existing competition was ended, not whether new competition was started. The word meaning to reproduce or copy implies duplication, which is unrelated to the passage''s argument about whether competition survived under monopoly conditions. The word meaning to honor the memory of relates to remembrance and ceremony, which has no connection to the economic dynamics described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QLOS58', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Professor Anais Mercier, a specialist in computational fluid dynamics at the Polytechnic Institute of Lausanne ______ demonstrated through a series of wind-tunnel experiments that the aerodynamic drag on commercial aircraft fuselages could be reduced by as much as eleven percent with biomimetic surface texturing.', $lyceon_json$[{"key":"A","text":", has demonstrated"},{"key":"B","text":"has demonstrated"},{"key":"C","text":"; has demonstrated"},{"key":"D","text":"— has demonstrated"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive appositive ''a specialist in computational fluid dynamics at the Polytechnic Institute of Lausanne'' renames ''Professor Anais Mercier'' and must be enclosed by matching punctuation. Since the appositive opens with a comma after ''Mercier,'' it must close with a comma before ''has demonstrated.'' Omitting the closing comma leaves the appositive unresolved, blurring the boundary between the appositive and the predicate. A semicolon would incorrectly sever the subject from its verb, splitting the main clause in two. A dash creates a mismatched pair with the opening comma, violating standard conventions for setting off appositives.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TBK5HF', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Cognitive scientist Elina Korhonen has questioned the prevailing assumption that bilingual children''s occasional mixing of languages within a single sentence—known as code-switching—indicates incomplete mastery of either language. Korhonen''s longitudinal study of 139 Finnish-Estonian bilingual children aged four through nine revealed that code-switching instances overwhelmingly adhered to the grammatical constraints of both languages simultaneously: children inserted Estonian nouns into Finnish sentence frames only at syntactic positions where both Finnish and Estonian grammar permitted a noun phrase, and they applied the morphological inflections required by the matrix language. Korhonen argues that far from signaling confusion, such precise code-switching demonstrates that bilingual children maintain two fully operational grammatical systems and deploy them with a combinatorial sophistication that monolingual speech does not require. She cautions, however, that educators who interpret code-switching as a deficit may inadvertently discourage a linguistic behavior that reflects advanced grammatical competence.', $lyceon_json$[{"key":"A","text":"Code-switching in bilingual children follows the grammatical rules of both languages, indicating advanced competence rather than incomplete mastery."},{"key":"B","text":"Bilingual children who code-switch frequently will eventually lose fluency in one of their two languages."},{"key":"C","text":"Finnish and Estonian share enough grammatical similarities that bilingual speakers can interchange elements freely without violating either language's rules."},{"key":"D","text":"Educators should actively encourage bilingual children to code-switch more frequently in classroom settings to develop their cognitive flexibility."}]$lyceon_json$::jsonb, 'A', NULL, E'Korhonen''s central claim is that bilingual children''s code-switching obeys the grammatical constraints of both languages, which demonstrates two fully operational grammatical systems rather than confusion or incomplete mastery. The choice connecting grammatically constrained code-switching to advanced competence captures this claim. The prediction that frequent code-switchers will lose fluency contradicts Korhonen''s argument that code-switching reflects maintained dual competence, not language attrition. The claim that Finnish and Estonian grammar can be freely interchanged misreads the passage; Korhonen found that switches occur only at positions permitted by both grammars, implying constraints rather than free interchangeability. The recommendation to encourage more code-switching in classrooms goes beyond Korhonen''s argument, which cautions against discouraging it but does not prescribe actively promoting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TBMJHO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fellowship committee, which reviews applications from over forty countries and which, after consulting with an external panel of seven distinguished ______ selects no more than three recipients per cycle, announced this year''s awardees at a ceremony in Copenhagen.', $lyceon_json$[{"key":"A","text":"scholars, selects"},{"key":"B","text":"scholars selects"},{"key":"C","text":"scholars; selects"},{"key":"D","text":"scholars. Selects"}]$lyceon_json$::jsonb, 'A', NULL, E'Within the nonrestrictive relative clause (''which reviews applications... and which... selects no more than three recipients per cycle''), a parenthetical adverbial phrase (''after consulting with an external panel of seven distinguished scholars'') is set off by commas. Because this parenthetical opens with a comma after the second ''which,'' it must close with a comma after ''scholars'' so the relative clause can continue with ''selects.'' Omitting the closing comma leaves the parenthetical unresolved, creating confusion about where the adverbial phrase ends and the verb of the relative clause begins. A semicolon would fragment the interior of the relative clause at an inappropriate structural point. A period after ''scholars'' would sever the relative clause from the main clause entirely, producing a fragment beginning with ''Selects'' that has no grammatical connection to the subject ''the fellowship committee.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U4NCLK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Veterinary researcher Oluwaseun Adeyemi studied sleep patterns in domesticated goats across thirteen farms in central Nigeria. Adeyemi found that goats housed in enclosures with solid wooden walls slept an average of 47 minutes longer per night than goats housed in open-sided shelters with wire fencing. She attributes this difference to the reduced sensory exposure in solid-walled enclosures: without visual and auditory access to nighttime activity outside the shelter, the goats experienced fewer startle-induced awakenings. Based on Adeyemi''s findings, a farmer who replaced an open-sided wire shelter with a solid-walled enclosure would most likely observe that the goats ________', $lyceon_json$[{"key":"A","text":"sleep longer at night due to fewer disturbances from external stimuli."},{"key":"B","text":"become more aggressive toward one another because of the confined environment."},{"key":"C","text":"refuse to enter the new enclosure for several months."},{"key":"D","text":"show no change in sleep duration regardless of the enclosure type."}]$lyceon_json$::jsonb, 'A', NULL, E'Adeyemi''s research directly links solid-walled enclosures to longer sleep through reduced sensory disturbance. Replacing an open-sided shelter with solid walls would logically produce the same effect. The prediction of increased aggression introduces a behavioral outcome not discussed or implied in the passage. The prediction that goats would refuse entry for months overstates a potential adjustment period far beyond anything the passage suggests. The prediction of no sleep change contradicts Adeyemi''s central finding that enclosure type is associated with measurable differences in sleep duration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U4RNCZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Ephraim Okoro has documented that speakers of Igbo in southeastern Nigeria increasingly substitute English loanwords for traditional kinship terms when conversing in urban settings. This lexical shift, Okoro argues, reflects not a decline in Igbo fluency but an adaptation to multilingual social environments where English carries professional prestige. ______ rural Igbo communities surveyed by Okoro''s team show no comparable pattern of loanword substitution, suggesting that the phenomenon is tied to urbanization rather than to any inherent instability in the language.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"As a result,"},{"key":"C","text":"In other words,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence introduces rural communities that do not exhibit the loanword substitution described in urban settings, establishing a direct comparison between two different environments. The transition "By contrast" correctly signals this opposing observation. The option "As a result" implies the rural finding is a consequence of the urban phenomenon, but the passage presents the two as parallel observations, not a cause-effect chain. The option "In other words" signals a restatement, yet the final sentence introduces new data about rural communities rather than rephrasing the urban finding. The option "Likewise" indicates similarity, but the rural communities'' lack of loanword substitution is the opposite of the urban pattern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ULR3FO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Throughout the 19th century, cartographers depicted Africa''s interior as largely blank, reinforcing European perceptions of the continent as an unmapped void. In reality, Arab and Swahili traders had maintained detailed route knowledge connecting Zanzibar to the Great Lakes region for generations, passing geographic intelligence through oral tradition and manuscript itineraries. When European explorers such as Richard Burton arrived at Lake Tanganyika in 1858, they relied heavily on these existing networks — hiring local guides, purchasing route descriptions, and following established trade paths — even as they presented their journeys as original discoveries in published accounts.', $lyceon_json$[{"key":"A","text":"It challenges a historical misconception by presenting evidence of pre-existing geographic knowledge and then showing how European explorers both relied on and obscured that knowledge."},{"key":"B","text":"It traces the chronological development of African cartography from indigenous oral traditions to European printed maps."},{"key":"C","text":"It contrasts the mapping techniques of two rival groups of explorers and evaluates which produced more accurate geographic records."},{"key":"D","text":"It argues that 19th-century European maps of Africa were deliberately falsified to serve colonial economic interests."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves from a misconception (blank maps implying an unmapped continent), to evidence countering it (Arab and Swahili traders'' detailed route knowledge), to a demonstration of how European explorers relied on that knowledge while presenting their journeys as original. This matches the option about challenging a misconception, presenting evidence, and showing how explorers relied on and obscured existing knowledge. The option about chronological development of cartography overstates the passage''s scope; it does not trace a progression from oral traditions to printed maps but rather highlights a specific contradiction. The option about contrasting rival mapping techniques mischaracterizes the text; the passage does not compare techniques or evaluate accuracy between two groups. The option about deliberate falsification for colonial economics goes beyond what the text states; the passage describes explorers presenting journeys as original discoveries, not deliberately falsifying maps for economic purposes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UZY6KO', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an interdisciplinary essay on fermentation and wants to present a claim that links the biochemistry of fermentation to its cultural significance, drawing on evidence from both domains. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VSAUB3', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The philosopher Kwame Gyekye has argued that communitarian ethics in Akan society do not ______ individual moral agency; rather, the community provides the relational context within which individuals exercise genuine — though not unlimited — autonomy in their ethical deliberations.', $lyceon_json$[{"key":"A","text":"preclude"},{"key":"B","text":"ratify"},{"key":"C","text":"embellish"},{"key":"D","text":"arbitrate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage uses a ''do not ... rather'' construction to argue against the idea that communitarian ethics prevent individual moral agency, then clarifies that autonomy exists within a relational context. The word meaning to make impossible or prevent fits this structure precisely: Gyekye''s claim is that communitarianism does not rule out individual agency. The word meaning to formally approve or sanction describes endorsement, but the passage is about whether individual agency is blocked, not whether it is formally endorsed. The word meaning to add decorative or fictitious details describes ornamentation, which is unrelated to whether a philosophical framework allows for moral agency. The word meaning to settle a dispute as a neutral third party describes conflict resolution, which does not apply to the relationship between communitarian ethics and individual agency.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YDBYNL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research paper on pollinator conservation and wants to argue that native wildflower plantings are more effective than non-native ornamental gardens at supporting bee populations. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
